css:
/* ============================================================
   GLOBAL RESET
============================================================ */
*, *::before, *::after {
    margin: 0; padding: 0;
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

html, body {
    width: 100%;
    min-height: 100vh;
    font-family: 'Nunito', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 16px;
    background: #f5f5f0;
    overflow-x: hidden;
}

#login-section, #app-section { display: none; }

/* ============================================================
   HIDE FRAPPE CHROME
============================================================ */
.navbar, nav.navbar, .page-header, .web-footer,
footer, .navbar-home, .container > .row > .col-sm-12 > nav {
    display: none !important;
}
.page-content-wrapper { padding: 0 !important; margin: 0 !important; }
.container { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }

/* ============================================================
   LOADING
============================================================ */
#loading-screen {
    position: fixed; inset: 0;
    background: #1c1c1e;
    display: flex; align-items: center; justify-content: center;
    z-index: 9999; flex-direction: column; gap: 16px;
}
.loading-emoji {
    font-size: 60px;
    animation: loadpulse 1.4s ease-in-out infinite;
}
@keyframes loadpulse { 0%,100%{transform:scale(1) rotate(0deg)} 50%{transform:scale(1.15) rotate(8deg)} }
.loading-text { color: rgba(255,255,255,.5); font-size: 14px; letter-spacing: 1px; }

/* ============================================================
   LOGIN
============================================================ */
.login-page {
    min-height: 100vh;
    background: #1c1c1e;
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    padding: 32px 20px;
}
.login-top { text-align: center; margin-bottom: 32px; }
.login-emoji {
    font-size: 68px; display: block; margin-bottom: 16px;
    animation: float 3s ease-in-out infinite;
}
@keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
.login-title {
    font-size: 32px; font-weight: 900;
    color: #fff; letter-spacing: -1px;
}
.login-title span { color: #f4a100; }
.login-sub { font-size: 14px; color: rgba(255,255,255,.4); margin-top: 6px; }

.login-error-box {
    width: 100%; max-width: 360px; display: none;
    background: rgba(255,59,48,.12); border: 1px solid rgba(255,59,48,.35);
    color: #ff6b6b; border-radius: 12px; padding: 12px 16px;
    font-size: 14px; text-align: center; margin-bottom: 14px;
}

.login-card {
    width: 100%; max-width: 360px;
    background: #2c2c2e;
    border-radius: 24px; padding: 28px 24px;
}

.input-group { margin-bottom: 16px; }
.input-label {
    display: block; font-size: 11px; font-weight: 700;
    color: rgba(255,255,255,.45); margin-bottom: 8px;
    text-transform: uppercase; letter-spacing: 1px;
}
.login-input {
    width: 100%; padding: 14px 16px;
    background: #3a3a3c;
    border: 1.5px solid transparent;
    border-radius: 12px; color: #fff; font-size: 15px;
    outline: none; transition: border-color .2s;
}
.login-input:focus { border-color: #f4a100; }
.login-input::placeholder { color: rgba(255,255,255,.2); }
.input-pw-wrap { position: relative; }
.pw-toggle {
    position: absolute; right: 13px; top: 50%;
    transform: translateY(-50%);
    background: none; border: none; cursor: pointer;
    font-size: 17px; opacity: .5; padding: 0;
}
.pw-toggle:hover { opacity: .9; }

.login-submit-btn {
    width: 100%; padding: 15px;
    background: #f4a100; color: #1c1c1e;
    border: none; border-radius: 14px;
    font-size: 16px; font-weight: 800; cursor: pointer;
    margin-top: 8px; letter-spacing: .3px;
    transition: transform .15s, opacity .15s;
}
.login-submit-btn:active { transform: scale(0.97); }
.login-submit-btn:disabled { opacity: .55; cursor: not-allowed; }
.login-help { color: rgba(255,255,255,.25); font-size: 12px; text-align: center; margin-top: 20px; }

/* ============================================================
   APP SHELL
============================================================ */
.app-page {
    min-height: 100vh;
    background: #f5f5f0;
    max-width: 480px;
    margin: 0 auto;
    padding-bottom: 110px;
    position: relative;
}

/* ============================================================
   HEADER — COMPACT VERSION
============================================================ */
.app-header {
    background: #1c1c1e;
    padding: 14px 16px 12px;
    position: relative;
}

.header-name {
    font-size: 16px;
    font-weight: 900;
    color: #fff;
    margin: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.header-date {
    font-size: 11px;
    color: rgba(255,255,255,.4);
    margin-top: 3px;
}

/* ============================================================
   STATUS STRIP
============================================================ */
.status-strip {
    display: flex; gap: 8px;
    padding: 14px 16px;
    background: #1c1c1e;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}
.status-strip::-webkit-scrollbar { display: none; }
.status-pill {
    display: flex; align-items: center; gap: 6px;
    background: #2c2c2e;
    border-radius: 20px; padding: 7px 14px;
    font-size: 12px; font-weight: 700;
    white-space: nowrap; flex-shrink: 0;
    color: rgba(255,255,255,.5);
}
.status-pill.pending  { background: rgba(244,161,0,.15);  color: #f4a100; }
.status-pill.consumed { background: rgba(52,199,89,.15);  color: #34c759; }
.status-pill.missed   { background: rgba(255,59,48,.12);  color: #ff453a; }
.status-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
.status-pill.pending  .status-dot { background: #f4a100; }
.status-pill.consumed .status-dot { background: #34c759; }
.status-pill.missed   .status-dot { background: #ff453a; }

/* ============================================================
   SECTION LABEL
============================================================ */
.section-label {
    font-size: 11px; font-weight: 800;
    color: #999; text-transform: uppercase; letter-spacing: 1.2px;
    padding: 12px 16px 8px;
}

/* ============================================================
   MENU CARD — FRAME STYLE
============================================================ */
.menu-card {
    background: #ffffff;
    border-radius: 20px;
    margin: 0 14px;
    padding: 14px;
    box-shadow: 0 8px 28px rgba(0,0,0,0.06);
}

.menu-card-header {
    padding-bottom: 10px;
    margin-bottom: 8px;
    border-bottom: 1px solid #f0ede6;
}

.menu-card-title {
    font-size: 15px;
    font-weight: 900;
    color: #1c1c1e;
    letter-spacing: -0.4px;
}

/* ============================================================
   MENU LIST
============================================================ */
.menu-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

/* ============================================================
   SLOT FRAME (OUTER BORDER)
============================================================ */
.menu-item {
    position: relative;
    border: 2px solid #e6e3da;
    border-radius: 14px;
    background: #ffffff;
    padding: 12px 12px 12px;
    transition: all 0.25s ease;
}

/* FIX: background matches menu-card (#ffffff) not page (#f5f5f0) */
.meal-slot-title {
    position: absolute;
    top: -10px;
    left: 18px;
    background: #ffffff;
    padding: 0 10px;
    font-size: 12px;
    font-weight: 900;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #8e8e93;
}

/* ============================================================
   MEAL CONTENT
============================================================ */
.menu-label {
    display: flex;
    align-items: center;
    gap: 16px;
    cursor: pointer;
    border: none;
    box-shadow: none;
    background: transparent;
    width: 100%;
}

.meal-emoji {
    font-size: 26px;
    width: 44px;
    height: 44px;
    background: #f7f6f1;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.meal-details {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.meal-type-txt {
    display: none; /* hidden — slot title shows type instead */
}

.meal-name-txt {
    font-size: 14px;
    font-weight: 900;
    color: #1c1c1e;
}

.meal-desc-txt {
    font-size: 12px;
    color: #9c9c9c;
    margin-top: 2px;
}

/* ============================================================
   SELECTION INDICATOR
============================================================ */
.menu-checkbox {
    display: none;
}

/* Right side selection circle */
.menu-label::after {
    content: '';
    width: 24px;
    height: 24px;
    border-radius: 50%;
    border: 2px solid #d9d6cc;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

/* FIX: selected targets .menu-item not .menu-label */
.menu-item.selected {
    border-color: #f4a100;
    box-shadow: 0 8px 22px rgba(244,161,0,0.18);
}

.menu-item.selected .meal-slot-title {
    color: #f4a100;
}

.menu-item.selected .menu-label::after {
    background: #f4a100;
    border-color: #f4a100;
    box-shadow: 0 0 0 5px rgba(244,161,0,0.18);
}

/* ============================================================
   EMPTY STATE
============================================================ */
.menu-empty {
    text-align: center;
    padding: 40px 20px;
    color: #bdbdbd;
    font-size: 14px;
}

.menu-empty-icon {
    font-size: 48px;
    margin-bottom: 12px;
}

/* ============================================================
   SUBMIT BUTTON
============================================================ */
.submit-order-btn {
    width: 100%;
    margin-top: 14px;
    padding: 14px;
    background: linear-gradient(135deg, #f4a100, #ffb733);
    color: #1c1c1e;
    border: none;
    border-radius: 14px;
    font-size: 15px;
    font-weight: 900;
    cursor: pointer;
    letter-spacing: .3px;
    box-shadow: 0 6px 18px rgba(244,161,0,0.3);
    transition: transform .15s ease, box-shadow .15s ease;
}

.submit-order-btn:active {
    transform: scale(0.97);
    box-shadow: 0 4px 12px rgba(244,161,0,0.25);
}

/* ============================================================
   SCAN OVERLAY — mobile centered modal style
============================================================ */
#scan-overlay {
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.85);
    z-index: 500;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    display: none;
}
#scan-overlay.open { display: flex; }

.scan-modal {
    width: 100%;
    max-width: 380px;
    margin: 0 16px;
    background: #1c1c1e;
    border-radius: 24px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 60px rgba(0,0,0,0.6);
}

.scan-topbar {
    display: flex; align-items: center; justify-content: space-between;
    padding: 16px 18px 12px;
    position: static;
    background: #2c2c2e;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}
.scan-title { color: #fff; font-size: 16px; font-weight: 800; }
.scan-close {
    background: rgba(255,255,255,.12);
    border: none; color: #fff;
    width: 30px; height: 30px;
    border-radius: 50%; font-size: 14px; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
}

.scan-viewport {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 1;
    overflow: hidden;
    background: #000;
}

#qr-reader {
    width: 100%;
    height: 100%;
}
#qr-reader video {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block;
}
#qr-reader img { display: none !important; }
/* hide html5-qrcode default UI chrome */
#qr-reader > div:not(#qr-shaded-region) { display: none !important; }
#qr-reader__scan_region { width: 100% !important; height: 100% !important; }

.scan-frame-wrap {
    position: absolute; inset: 0;
    display: flex; align-items: center; justify-content: center;
    pointer-events: none; z-index: 5;
}
.scan-frame {
    width: 200px; height: 200px;
    position: relative;
}
.scan-frame::before, .scan-frame::after,
.scan-frame span::before, .scan-frame span::after {
    content: '';
    position: absolute;
    width: 30px; height: 30px;
    border-color: #f4a100;
    border-style: solid;
}
.scan-frame::before   { top:0;    left:0;   border-width: 4px 0 0 4px; border-radius: 4px 0 0 0; }
.scan-frame::after    { top:0;    right:0;  border-width: 4px 4px 0 0; border-radius: 0 4px 0 0; }
.scan-frame span::before { bottom:0; left:0;   border-width: 0 0 4px 4px; border-radius: 0 0 0 4px; }
.scan-frame span::after  { bottom:0; right:0;  border-width: 0 4px 4px 0; border-radius: 0 0 4px 0; }

.scan-status-bar {
    padding: 14px 16px 18px;
    background: #1c1c1e;
    position: static;
    backdrop-filter: none;
}
.scan-hint { color: rgba(255,255,255,.55); font-size: 13px; text-align: center; margin-bottom: 8px; }

.result-success {
    background: rgba(52,199,89,.15);
    border: 1px solid rgba(52,199,89,.35);
    color: #34c759; border-radius: 12px;
    padding: 10px 14px; font-size: 13px; font-weight: 600;
    line-height: 1.5;
}
.result-error {
    background: rgba(255,59,48,.12);
    border: 1px solid rgba(255,59,48,.3);
    color: #ff453a; border-radius: 12px;
    padding: 10px 14px; font-size: 13px; font-weight: 600;
    line-height: 1.5;
}
.result-warning {
    background: rgba(255,149,0,.12);
    border: 1px solid rgba(255,149,0,.3);
    color: #ff9500; border-radius: 12px;
    padding: 10px 14px; font-size: 13px; font-weight: 600;
    line-height: 1.5;
}

/* ============================================================
   BOTTOM BAR
============================================================ */
.bottom-bar {
    position: fixed; bottom: 0; left: 50%;
    transform: translateX(-50%);
    width: 100%; max-width: 480px;
    background: #fff;
    border-top: 1px solid #eeede8;
    padding: 12px 8px 28px;
    display: flex; justify-content: space-around; align-items: center;
    z-index: 100;
}
.bar-item {
    display: flex; flex-direction: column;
    align-items: center; gap: 5px; cursor: pointer;
    flex: 1;
}
.bar-btn {
    width: 48px; height: 48px;
    border-radius: 14px;
    display: flex; align-items: center; justify-content: center;
    font-size: 20px; transition: transform .12s;
    cursor: pointer; border: none;
}
.bar-btn:active { transform: scale(0.88); }

.bar-scan-wrap {
    display: flex; flex-direction: column;
    align-items: center; gap: 5px; cursor: pointer; flex: 1.4;
}
.bar-scan-btn {
    display: flex; align-items: center; gap: 8px;
    background: #2c3e50;
    color: #fff; border: none;
    padding: 11px 22px;
    border-radius: 50px;
    font-size: 14px; font-weight: 800; cursor: pointer;
    box-shadow: 0 4px 14px rgba(44,62,80,.3);
    transition: transform .12s, background .2s;
    white-space: nowrap;
}
.bar-scan-btn:active { transform: scale(0.94); }
.bar-scan-btn.scanning {
    background: #e74c3c;
    box-shadow: 0 4px 14px rgba(231,76,60,.4);
}
.scan-btn-icon { font-size: 18px; }

.bar-btn-icon { background: #f5f5f0; }
.bar-label { font-size: 10px; font-weight: 700; color: #aaa; }

@media (max-width: 360px) {
    .header-name { font-size: 13px; }
    .bar-scan-btn { padding: 10px 16px; font-size: 13px; }
}

/* ============================================================
   TODAY STATUS CARD
============================================================ */
.today-status-card {
    background: #fff;
    border-radius: 16px;
    margin: 10px 14px 0;
    box-shadow: 0 4px 16px rgba(0,0,0,0.06);
    overflow: hidden;
}
.tsc-header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 10px 14px;
    background: #1c1c1e;
}
.tsc-title {
    font-size: 13px; font-weight: 800;
    color: #fff; letter-spacing: .3px;
}
.tsc-toggle {
    background: rgba(255,255,255,.12);
    border: none; color: rgba(255,255,255,.7);
    font-size: 11px; font-weight: 700;
    padding: 4px 10px; border-radius: 20px;
    cursor: pointer;
}
.tsc-body { padding: 12px 14px 10px; }
.tsc-pills { display: flex; gap: 8px; }
.tsc-pill {
    flex: 1; display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    gap: 3px; padding: 10px 6px;
    border-radius: 12px; text-align: center;
}
.tsc-pill-loading { color: #aaa; font-size: 12px; padding: 8px 0; }
.tsc-pill .pill-icon  { font-size: 20px; }
.tsc-pill .pill-label { font-size: 11px; font-weight: 800; letter-spacing: .3px; }
.tsc-pill .pill-status{ font-size: 10px; font-weight: 600; }
.tsc-pill.consumed  { background: rgba(52,199,89,.12);  color: #27ae60; }
.tsc-pill.pending   { background: rgba(244,161,0,.12);  color: #e67e00; }
.tsc-pill.missed    { background: rgba(255,59,48,.10);  color: #e74c3c; }
.tsc-pill.nordered  { background: #f5f5f5; color: #bbb; }
.tsc-counts { display: flex; gap: 6px; margin-top: 10px; }
.tsc-count-item {
    flex: 1; text-align: center;
    background: #f7f6f1; border-radius: 10px; padding: 6px 4px;
}
.tsc-count-num { font-size: 18px; font-weight: 900; color: #1c1c1e; display: block; }
.tsc-count-lbl { font-size: 9px; font-weight: 700; color: #aaa; text-transform: uppercase; letter-spacing: .5px; }

/* ============================================================
   REPORT OVERLAY (bottom sheet)
============================================================ */
#report-overlay {
    display: none; position: fixed; inset: 0;
    background: rgba(0,0,0,0.6); z-index: 600;
    align-items: flex-end; justify-content: center;
}
#report-overlay.open { display: flex; }
.report-sheet {
    width: 100%; max-width: 480px; background: #fff;
    border-radius: 24px 24px 0 0; max-height: 92vh;
    display: flex; flex-direction: column; overflow: hidden;
    animation: slideUp .25s ease;
}
@keyframes slideUp { from{transform:translateY(100%)} to{transform:translateY(0)} }
.report-sheet-header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 16px 18px 12px; border-bottom: 1px solid #f0ede6; flex-shrink: 0;
}
.report-sheet-title { font-size: 16px; font-weight: 900; color: #1c1c1e; }
.report-sheet-close {
    background: #f0ede6; border: none; width: 28px; height: 28px;
    border-radius: 50%; font-size: 13px; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
}
.report-sheet-body { overflow-y: auto; flex: 1; padding: 14px 16px; }
.report-date-row { display: flex; gap: 10px; margin-bottom: 12px; }
.report-date-group { flex: 1; display: flex; flex-direction: column; gap: 4px; }
.report-date-label { font-size: 11px; font-weight: 700; color: #888; text-transform: uppercase; letter-spacing: .8px; }
.report-date-input {
    width: 100%; padding: 10px 12px; border: 1.5px solid #e6e3da;
    border-radius: 10px; font-size: 14px; color: #1c1c1e; outline: none; transition: border-color .2s;
}
.report-date-input:focus { border-color: #f4a100; }
.report-gen-btn {
    width: 100%; padding: 13px; background: linear-gradient(135deg,#f4a100,#ffb733);
    color: #1c1c1e; border: none; border-radius: 12px; font-size: 14px; font-weight: 900;
    cursor: pointer; margin-bottom: 14px; transition: transform .15s;
}
.report-gen-btn:active { transform: scale(0.97); }
.report-table-wrap { overflow-x: auto; border-radius: 12px; border: 1px solid #e6e3da; }
.report-table { width: 100%; border-collapse: collapse; font-size: 12px; min-width: 340px; }
.report-table th {
    background: #1c1c1e; color: #fff; padding: 9px 8px;
    text-align: center; font-size: 11px; font-weight: 700; letter-spacing: .5px; white-space: nowrap;
}
.report-table th:first-child { text-align: left; }
.report-table td { padding: 8px; text-align: center; border-bottom: 1px solid #f0ede6; color: #333; }
.report-table td:first-child { text-align: left; font-weight: 700; color: #1c1c1e; white-space: nowrap; }
.report-table tr:last-child td { border-bottom: none; }
.report-table tr:nth-child(even) td { background: #fafaf8; }
.badge-consumed { color: #27ae60; font-weight: 700; }
.badge-pending  { color: #e67e00; font-weight: 700; }
.badge-missed   { color: #e74c3c; font-weight: 700; }
.badge-none     { color: #bbb; }
.fine-cell      { color: #e74c3c; font-weight: 900; }
.fine-zero      { color: #27ae60; font-weight: 700; }
.report-summary { display: flex; gap: 8px; margin-top: 12px; }
.report-sum-box { flex: 1; background: #f7f6f1; border-radius: 10px; padding: 10px 8px; text-align: center; }
.report-sum-num { font-size: 18px; font-weight: 900; color: #1c1c1e; display: block; }
.report-sum-lbl { font-size: 10px; font-weight: 700; color: #aaa; text-transform: uppercase; }
.report-sum-box.fine-box .report-sum-num { color: #e74c3c; }
.report-dl-btn {
    width: 100%; padding: 12px; background: #1c1c1e; color: #fff;
    border: none; border-radius: 12px; font-size: 14px; font-weight: 800;
    cursor: pointer; margin-top: 12px;
    display: flex; align-items: center; justify-content: center; gap: 8px; transition: transform .15s;
}
.report-dl-btn:active { transform: scale(0.97); }
.report-empty { text-align: center; padding: 32px 16px; color: #bbb; font-size: 14px; }

/* ============================================================
   FEEDBACK OVERLAY
============================================================ */
#feedback-overlay {
    display: none; position: fixed; inset: 0;
    background: rgba(0,0,0,0.6); z-index: 600;
    align-items: flex-end; justify-content: center;
}
#feedback-overlay.open { display: flex; }

.fb-section {
    background: #fafaf8;
    border: 1px solid #eeede8;
    border-radius: 14px;
    padding: 14px;
    margin-bottom: 12px;
}
.fb-section-title {
    font-size: 14px; font-weight: 900; color: #1c1c1e;
    display: flex; align-items: center; gap: 6px;
    margin-bottom: 10px;
}
.fb-row {
    display: flex; align-items: center; justify-content: space-between; gap: 8px;
}
.fb-label {
    font-size: 12px; font-weight: 700; color: #666;
    display: block;
}
.fb-toggle-group {
    display: flex; gap: 6px; flex-shrink: 0;
}
.fb-toggle {
    padding: 5px 12px;
    border: 1.5px solid #e0ddd6;
    border-radius: 20px; background: #fff;
    font-size: 12px; font-weight: 700; cursor: pointer;
    color: #888; transition: all .15s;
}
.fb-toggle.active {
    background: #f4a100; border-color: #f4a100;
    color: #1c1c1e;
}
.fb-textarea {
    width: 100%; margin-top: 6px;
    padding: 9px 12px;
    border: 1.5px solid #e6e3da;
    border-radius: 10px; font-size: 13px;
    color: #1c1c1e; outline: none; resize: none;
    height: 64px; font-family: inherit;
    background: #fff; transition: border-color .2s;
}
.fb-textarea:focus { border-color: #f4a100; }

/* ============================================================
   MOBILE FIX — ensure page content is visible
============================================================ */
/* Frappe web page sometimes wraps content in divs that clip on mobile */
.web-page-content,
.page-content,
main.page-content-wrapper,
.container-fluid {
    padding: 0 !important;
    margin: 0 !important;
    min-height: 100vh !important;
    overflow: visible !important;
}

/* Ensure app-section fills screen on mobile */
#app-section {
    min-height: 100vh;
    width: 100%;
    overflow-x: hidden;
}

/* iOS safe area support */
.bottom-bar {
    padding-bottom: calc(12px + env(safe-area-inset-bottom));
}
.app-page {
    padding-bottom: calc(110px + env(safe-area-inset-bottom));
}

/* Prevent text size adjustment on mobile */
html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
}

javascript:
/* ============================================================
   GLOBAL STATE
============================================================ */

var APP = {
    employeeId:        '',
    employeeName:      '',
    selectedMeals:     {},
    initialized:       false,
    scannerRunning:    false,
    html5QrCode:       null,
    existingOrderName: null
};

/* ============================================================
   ENTRY POINT — bulletproof, never gets stuck on loading
============================================================ */
$(document).ready(function () {
    showScreen('loading');
    // Go straight to API — most reliable across all Frappe versions and mobile
    $.ajax({
        url: '/api/method/frappe.auth.get_logged_user',
        type: 'GET',
        timeout: 8000,
        success: function(r) {
            var apiUser = r.message;
            if (apiUser && apiUser !== 'Guest') {
                APP.employeeId = apiUser;
                // Try session full name, fall back to email
                try {
                    APP.employeeName = (frappe.session && frappe.session.user_fullname)
                                       || apiUser;
                } catch(e) { APP.employeeName = apiUser; }
                showScreen('app');
                bootApp();
            } else {
                showScreen('login');
            }
        },
        error: function(xhr) {
            // Any error: show login — never stay on loading screen
            showScreen('login');
            if (xhr.status !== 401 && xhr.status !== 403) {
                showLoginError('Could not connect. Please check your network.');
            }
        }
    });
});

/* ============================================================
   INIT - CHECK SESSION (used after login)
============================================================ */
function initApp() {
    var user = (frappe.session && frappe.session.user) || null;
    if (user && user !== 'Guest') {
        APP.employeeId   = user;
        APP.employeeName = (frappe.session && frappe.session.user_fullname) || user;
        showScreen('app');
        bootApp();
    } else {
        showScreen('login');
    }
}

/* ============================================================
   FETCH LOGGED USER
============================================================ */
function fetchLoggedUser() {
    $.ajax({
        url: '/api/method/frappe.auth.get_logged_user',
        type: 'GET',
        success: function(r) {
            console.log("Logged user:", r);
            var user = r.message;
            if (user && user !== 'Guest') {
                APP.employeeId   = user;
                APP.employeeName = APP._loginFullName || user;
                showScreen('app');
                bootApp();
            } else {
                showScreen('login');
                showLoginError('Login failed. Please try again.');
                resetLoginBtn();
            }
        },
        error: function() {
            showScreen('login');
            showLoginError('Could not verify session. Please try again.');
            resetLoginBtn();
        }
    });
}

function verifyEmployee(user) {
    fetchLoggedUser();
}

/* ============================================================
   SCREEN MANAGER
============================================================ */
function showScreen(screen) {
    $('#loading-screen').hide();
    $('#login-section').hide();
    $('#app-section').hide();

    if (screen === 'loading') {
        $('#loading-screen').show();
    } else if (screen === 'login') {
        $('#login-section').show();
        attachLoginEvents();
    } else if (screen === 'app') {
        $('#app-section').show();
    }
}

/* ============================================================
   LOGIN EVENTS
============================================================ */
function attachLoginEvents() {
    if (APP.initialized) return;
    APP.initialized = true;

    $('#pw-toggle').off('click').on('click', function () {
        var inp = $('#login-password');
        if (inp.attr('type') === 'password') {
            inp.attr('type', 'text');
            $(this).text('🙈');
        } else {
            inp.attr('type', 'password');
            $(this).text('👁');
        }
    });

    $('#login-btn').off('click').on('click', function (e) {
        e.preventDefault();
        doLogin();
    });

    $('#login-email, #login-password').off('keypress').on('keypress', function (e) {
        if (e.which === 13) doLogin();
    });
}

/* ============================================================
   LOGIN LOGIC
============================================================ */
function doLogin() {
    var email    = $.trim($('#login-email').val());
    var password = $('#login-password').val();

    if (!email)    { showLoginError('Please enter your email address'); return; }
    if (!password) { showLoginError('Please enter your password');      return; }

    clearLoginError();
    $('#login-btn').prop('disabled', true).text('Signing in...');
    showScreen('loading');

    var csrfToken = frappe.csrf_token || $('[name="csrf_token"]').val() || '';

    $.ajax({
        url: '/api/method/login',
        type: 'POST',
        data: { usr: email, pwd: password },
        headers: {
            'X-Frappe-CSRF-Token': csrfToken,
            'X-Requested-With': 'XMLHttpRequest'
        },
        success: function (data) {
            console.log("Login response:", data);
            if (data.message === 'Logged In' || (data.message && data.message.message === 'Logged In')) {
                APP._loginFullName = data.full_name || (data.message && data.message.full_name) || '';
                fetchLoggedUser();
            } else {
                showScreen('login');
                showLoginError('Login failed. Please try again.');
                resetLoginBtn();
            }
        },
        error: function (xhr) {
            console.log("Login error:", xhr.status, xhr.responseText);
            showScreen('login');
            var msg = 'Invalid email or password';
            try {
                var res = JSON.parse(xhr.responseText);
                if (res._server_messages) {
                    var msgs = JSON.parse(res._server_messages);
                    if (msgs.length > 0) {
                        var m = JSON.parse(msgs[0]);
                        msg = m.message || msg;
                    }
                } else if (res.message) {
                    msg = res.message;
                } else if (res.exc) {
                    msg = 'Invalid credentials';
                }
            } catch (e) {}
            showLoginError(msg);
            resetLoginBtn();
        }
    });
}

function showLoginError(msg) { $('#login-error').text(msg).show(); }
function clearLoginError()   { $('#login-error').hide().text(''); }
function resetLoginBtn()     { $('#login-btn').prop('disabled', false).text('Login'); }

/* ============================================================
   LOGOUT
============================================================ */
function performLogout(notSystemUser) {
    showScreen('loading');

    $.ajax({
        url: '/api/method/logout',
        type: 'POST',
        complete: function () {
            APP.employeeId    = '';
            APP.employeeName  = '';
            APP.selectedMeals = {};
            APP.initialized   = false;

            $('#login-email').val('');
            $('#login-password').val('');
            clearLoginError();
            resetLoginBtn();

            showScreen('login');

            if (notSystemUser) {
                setTimeout(function () {
                    showLoginError('Access denied. You must be a registered System User.');
                }, 300);
            }
        }
    });
}

/* ============================================================
   BOOT APP
============================================================ */
function bootApp() {
    setAppDate();
    $('#emp-name').text('Hi, ' + APP.employeeName);
    $('#tsc-body').hide();
    $('#tsc-toggle').text('▼ Show');
    loadTodayStatus();
    loadTomorrowMenu();
    attachAppEvents();
}

/* ============================================================
   DATE
============================================================ */
function setAppDate() {
    var days   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var now    = new Date();
    var str    = days[now.getDay()] + ', ' + now.getDate() + ' ' + months[now.getMonth()] + ' ' + now.getFullYear();
    $('#app-date').text(str);
}

/* ============================================================
   APP EVENTS
============================================================ */
function attachAppEvents() {
    // FIX: scan button toggles overlay open/close
    $('#scan-btn').off('click').on('click', function(e) {
        e.preventDefault();
        if (APP.scannerRunning) {
            stopQRScanner();
        } else {
            openQRScanner();
        }
    });

    // FIX: close button on overlay
    $('#scan-close').off('click').on('click', function(e) {
        e.preventDefault();
        stopQRScanner();
    });

    $('#submit-btn').off('click').on('click',   function(e) { e.preventDefault(); submitOrder();        });
    $('#bar-qr').off('click').on('click',        function(e) { e.preventDefault(); showQR();             });
    $('#bar-feedback').off('click').on('click',  function(e) { e.preventDefault(); openFeedback();       });
    $('#bar-report').off('click').on('click',    function(e) { e.preventDefault(); openReport();         });
    $('#bar-logout').off('click').on('click',    function(e) { e.preventDefault(); performLogout(false); });

    // Today status toggle
    $('#tsc-toggle').off('click').on('click', function() {
        var body = $('#tsc-body');
        if (body.is(':visible')) {
            body.hide();
            $(this).text('▼ Show');
        } else {
            body.show();
            $(this).text('▲ Hide');
        }
    });

    // Report overlay
    $('#report-close').off('click').on('click', function() {
        $('#report-overlay').removeClass('open');
    });
    $('#report-overlay').off('click').on('click', function(e) {
        if ($(e.target).is('#report-overlay')) $('#report-overlay').removeClass('open');
    });
    $('#report-gen-btn').off('click').on('click', function() { generateReport(); });

    // Feedback overlay
    $('#feedback-close').off('click').on('click', function() {
        $('#feedback-overlay').removeClass('open');
    });
    $('#feedback-overlay').off('click').on('click', function(e) {
        if ($(e.target).is('#feedback-overlay')) $('#feedback-overlay').removeClass('open');
    });
    $('#fb-submit-btn').off('click').on('click', function() { submitFeedback(); });

    // Yes/No toggles inside feedback
    $(document).off('click', '.fb-toggle').on('click', '.fb-toggle', function() {
        $(this).closest('.fb-toggle-group').find('.fb-toggle').removeClass('active');
        $(this).addClass('active');
    });
}

/* ============================================================
   MENU LOADING
============================================================ */
function loadTomorrowMenu() {
    var days     = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    var tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);

    var tomorrowDay  = days[tomorrow.getDay()];
    var tomorrowDate = tomorrow.toLocaleDateString('en-GB', {
        day: 'numeric', month: 'short', year: 'numeric'
    });

    $('#menu-card .card-title').html(
        '🍽️ Count me in for Tomorrow!<br>' +
        '<small style="font-size:12px;color:#aaa;font-weight:400;">' +
        tomorrowDay + ' &nbsp;·&nbsp; ' + tomorrowDate +
        '</small>'
    );

    $.ajax({
        url: '/api/method/frappe.client.get_list',
        type: 'GET',
        data: {
            doctype: 'Food Menu Item',
            filters: JSON.stringify([['day', '=', tomorrowDay]]),
            fields: JSON.stringify([
                'name', 'day', 'available',
                'breakfast_item', 'breakfast_description',
                'lunch_item',     'lunch_description',
                'dinner_item',    'dinner_description'
            ]),
            limit: 1
        },
        success: function(r) {
            var menu = r.message && r.message.length > 0 ? r.message[0] : null;
            if (menu && menu.available) {
                renderMenu(menu, tomorrowDay);
            } else if (menu && !menu.available) {
                showNoMenu(tomorrowDay, 'Menu is marked unavailable for ' + tomorrowDay);
            } else {
                showNoMenu(tomorrowDay, 'No menu set for ' + tomorrowDay + ' yet');
            }
        },
        error: function() {
            showNoMenu(tomorrowDay, 'No menu set for ' + tomorrowDay + ' yet');
        }
    });
}

function showNoMenu(day, msg) {
    $('#menu-list').html(
        '<div style="text-align:center;padding:28px 16px;">' +
        '<div style="font-size:52px;">🚫</div>' +
        '<p style="color:#888;margin-top:12px;font-weight:600;font-size:15px;">' + msg + '</p>' +
        '<p style="color:#bbb;font-size:12px;margin-top:6px;">Contact admin to update the menu</p>' +
        '</div>'
    );
    $('#submit-btn').hide();
}

function renderMenu(menu, dayName) {
    var meals = [
        { type: 'Breakfast', icon: '🌅', item: menu.breakfast_item, desc: menu.breakfast_description },
        { type: 'Lunch',     icon: '☀️',  item: menu.lunch_item,     desc: menu.lunch_description     },
        { type: 'Dinner',    icon: '🌙',  item: menu.dinner_item,    desc: menu.dinner_description    }
    ];

    var html = '';

    meals.forEach(function(meal) {
        if (!meal.item) return;

        html += '<div class="menu-item" id="item-' + meal.type.toLowerCase() + '">';

        // FIX: slot title rendered in JS so CSS cutout works
        html += '<span class="meal-slot-title">' + meal.type.toUpperCase() + '</span>';

        html += '<label class="menu-label" id="lbl-' + meal.type.toLowerCase() + '">';
        html += '<span class="meal-emoji">' + meal.icon + '</span>';
        html += '<span class="meal-details">';
        html += '<span class="meal-name-txt">' + meal.item + '</span>';
        if (meal.desc) {
            html += '<span class="meal-desc-txt">' + meal.desc + '</span>';
        }
        html += '</span>';
        html += '<input type="checkbox" class="menu-checkbox"' +
                ' data-type="' + meal.type + '"' +
                ' data-item="' + meal.item + '"' +
                ' data-menu="' + menu.name + '">';
        html += '</label>';
        html += '</div>';
    });

    $('#menu-list').html(html);
    $('#submit-btn').show();

    var tomorrowDate = frappe.datetime.add_days(frappe.datetime.nowdate(), 1);
    loadExistingOrder(tomorrowDate);

    // FIX: selected class applied to .menu-item (not .menu-label)
    $('.menu-checkbox').off('change').on('change', function() {
        var type = $(this).data('type');
        var item = $(this).data('item');
        var menu = $(this).data('menu');
        var menuItem = $(this).closest('.menu-item');

        if ($(this).is(':checked')) {
            APP.selectedMeals[type] = { item: item, menu: menu };
            menuItem.addClass('selected');
        } else {
            delete APP.selectedMeals[type];
            menuItem.removeClass('selected');
        }
    });
}

/* ============================================================
   ORDER SUBMISSION
============================================================ */
function loadExistingOrder(tomorrowDate) {
    $.ajax({
        url: '/api/method/frappe.client.get_list',
        type: 'GET',
        data: {
            doctype:  'Food Count',
            filters:  JSON.stringify([
                ['user',       '=', APP.employeeId],
                ['order_date', '=', tomorrowDate]
            ]),
            fields: JSON.stringify(['name','breakfast','lunch','dinner','breakfast_selected','lunch_selected','dinner_selected']),
            limit: 1
        },
        success: function(r) {
            APP.selectedMeals = {};
            $('.menu-item').removeClass('selected');
            $('.menu-checkbox').prop('checked', false);

            if (r.message && r.message.length > 0) {
                var existing = r.message[0];
                APP.existingOrderName = existing.name;

                // FIX: selected class on .menu-item not .menu-label
                $('.menu-checkbox').each(function() {
                    var type = $(this).data('type');
                    var checked = false;
                    if (type === 'Breakfast') checked = !!existing.breakfast_selected;
                    if (type === 'Lunch')     checked = !!existing.lunch_selected;
                    if (type === 'Dinner')    checked = !!existing.dinner_selected;

                    $(this).prop('checked', checked);
                    var menuItem = $(this).closest('.menu-item');
                    if (checked) {
                        menuItem.addClass('selected');
                        APP.selectedMeals[type] = {
                            item: $(this).data('item'),
                            menu: $(this).data('menu')
                        };
                    }
                });

                $('#submit-btn').text('Update My Order');
            } else {
                APP.existingOrderName = null;
                $('#submit-btn').text('Submit My Order');
            }
        }
    });
}

function submitOrder() {
    if (!APP.employeeId) {
        frappe.msgprint({ title: 'Error', message: 'User ID not found.', indicator: 'red' });
        return;
    }

    var days         = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    var tomorrow     = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    var tomorrowDay  = days[tomorrow.getDay()];
    var tomorrowDate = frappe.datetime.add_days(frappe.datetime.nowdate(), 1);

    var bfast  = APP.selectedMeals['Breakfast'] ? APP.selectedMeals['Breakfast'].item : '';
    var lunch  = APP.selectedMeals['Lunch']     ? APP.selectedMeals['Lunch'].item     : '';
    var dinner = APP.selectedMeals['Dinner']    ? APP.selectedMeals['Dinner'].item    : '';

    if (!bfast && !lunch && !dinner && !APP.existingOrderName) {
        frappe.msgprint({
            title: 'Nothing Selected',
            message: 'Please tick at least one meal to order.',
            indicator: 'orange'
        });
        return;
    }

    var bStatus = bfast  ? 'Pending' : 'Not Ordered';
    var lStatus = lunch  ? 'Pending' : 'Not Ordered';
    var dStatus = dinner ? 'Pending' : 'Not Ordered';

    if (APP.existingOrderName) {
        frappe.call({
            method: 'frappe.client.get',
            args: { doctype: 'Food Count', name: APP.existingOrderName },
            callback: function(r) {
                if (!r.message) return;
                var latestDoc = r.message;

                latestDoc.breakfast_selected = bfast ? 1 : 0;
                latestDoc.lunch_selected     = lunch ? 1 : 0;
                latestDoc.dinner_selected    = dinner ? 1 : 0;
                latestDoc.breakfast = bfast;
                latestDoc.lunch     = lunch;
                latestDoc.dinner    = dinner;

                if (latestDoc.breakfast_status !== 'Consumed') latestDoc.breakfast_status = bStatus;
                if (latestDoc.lunch_status     !== 'Consumed') latestDoc.lunch_status     = lStatus;
                if (latestDoc.dinner_status    !== 'Consumed') latestDoc.dinner_status    = dStatus;

                frappe.call({
                    method: 'frappe.client.save',
                    args:   { doc: latestDoc },
                    freeze: true,
                    freeze_message: 'Updating your order...',
                    callback: function(res) {
                        if (res.message) {
                            frappe.show_alert({ message: '✅ ' + tomorrowDay + ' order updated!', indicator: 'green' }, 5);
                        }
                    }
                });
            }
        });
    } else {
        frappe.call({
            method: 'frappe.client.insert',
            args: {
                doc: {
                    doctype:          'Food Count',
                    user:             APP.employeeId,
                    order_date:       tomorrowDate,
                    breakfast_selected: bfast ? 1 : 0,
                    lunch_selected:     lunch ? 1 : 0,
                    dinner_selected:    dinner ? 1 : 0,
                    breakfast:          bfast,
                    lunch:              lunch,
                    dinner:             dinner,
                    breakfast_status:   bStatus,
                    lunch_status:     lStatus,
                    dinner_status:    dStatus
                }
            },
            freeze: true,
            freeze_message: 'Submitting your order...',
            callback: function(r) {
                if (r.message) {
                    APP.existingOrderName = r.message.name;
                    $('#submit-btn').text('Update My Order');
                    frappe.show_alert({ message: '✅ ' + tomorrowDay + ' order submitted!', indicator: 'green' }, 5);
                }
            }
        });
    }
}

/* ============================================================
   QR SCANNER
============================================================ */
function openQRScanner() {
    var scanBtn    = $('#scan-btn');
    var scanResult = $('#scan-result');

    if (APP.scannerRunning) {
        stopQRScanner();
        return;
    }

    scanResult.html('');

    // FIX: show the overlay, not just #qr-reader
    $('#scan-overlay').css('display', 'flex');

    scanBtn.addClass('scanning')
           .html('<span class="scan-btn-icon">⏹</span><span class="scan-btn-text">Stop Scanner</span>');

    APP.html5QrCode = new Html5Qrcode("qr-reader");

    var config = {
        fps: 15,
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0,
        disableFlip: false
    };

    APP.html5QrCode.start(
        { facingMode: { exact: "environment" } },
        config,
        onQRScanSuccess,
        onQRScanError
    ).then(function() {
        APP.scannerRunning = true;
        console.log("Back camera started");
    }).catch(function(err) {
        console.log("Back camera failed, trying any camera:", err);

        APP.html5QrCode.start(
            { facingMode: "user" },
            config,
            onQRScanSuccess,
            onQRScanError
        ).then(function() {
            APP.scannerRunning = true;
            console.log("Front camera started");
        }).catch(function(err2) {
            console.log("All cameras failed:", err2);

            Html5Qrcode.getCameras().then(function(cameras) {
                if (cameras && cameras.length) {
                    APP.html5QrCode.start(
                        cameras[0].id,
                        config,
                        onQRScanSuccess,
                        onQRScanError
                    ).then(function() {
                        APP.scannerRunning = true;
                    }).catch(function(err3) {
                        handleCameraFail(err3);
                    });
                } else {
                    handleCameraFail("No cameras found");
                }
            }).catch(function(err3) {
                handleCameraFail(err3);
            });
        });
    });
}

function stopQRScanner() {
    if (APP.html5QrCode && APP.scannerRunning) {
        APP.html5QrCode.stop().then(function() {
            APP.scannerRunning = false;
            // FIX: hide the overlay, not just #qr-reader
            $('#scan-overlay').hide();
            resetScanBtn();
        }).catch(function(err) {
            console.log("Stop error:", err);
            APP.scannerRunning = false;
            $('#scan-overlay').hide();
            resetScanBtn();
        });
    } else {
        // If scanner never started, just close overlay
        $('#scan-overlay').hide();
        resetScanBtn();
    }
}

function handleCameraFail(err) {
    console.log("Camera failed completely:", err);
    APP.scannerRunning = false;
    $('#scan-overlay').hide();
    resetScanBtn();

    frappe.msgprint({
        title: 'Camera Not Available',
        message: 'Direct camera failed. Opening file picker instead...',
        indicator: 'orange'
    });

    setTimeout(function() {
        openFileScanner();
    }, 1000);
}

function resetScanBtn() {
    $('#scan-btn')
        .removeClass('scanning')
        .html('<span class="scan-btn-icon">⬛</span><span class="scan-btn-text">Scan QR</span>');
}

function onQRScanSuccess(decodedText, decodedResult) {
    console.log("QR Scanned:", decodedText);
    stopQRScanner();

    $('#scan-result').html(
        '<div class="result-success">' +
        '<strong>✅ Scanned Successfully!</strong><br>' +
        '<span style="font-size:13px;word-break:break-all;">' + decodedText + '</span>' +
        '</div>'
    );

    logQRScan(decodedText);
}

function onQRScanError(error) {
    // Runs continuously while scanning — ignore silently
}

function openFileScanner() {
    var input    = document.createElement('input');
    input.type   = 'file';
    input.accept = 'image/*';
    input.setAttribute('capture', 'environment');

    input.onchange = function(e) {
        var file = e.target.files[0];
        if (!file) return;

        $('#scan-result').html(
            '<p style="text-align:center;color:#aaa;padding:10px;font-size:14px;">⏳ Reading QR...</p>'
        );

        var scanner = new Html5Qrcode('qr-reader');

        scanner.scanFile(file, true)
            .then(function(text) {
                $('#scan-result').html(
                    '<div class="result-success">' +
                    '<strong>✅ Scanned!</strong><br>' +
                    '<span style="font-size:13px;">' + text + '</span>' +
                    '</div>'
                );
                logQRScan(text);
            })
            .catch(function() {
                $('#scan-result').html('');
                frappe.msgprint({
                    title: 'Could Not Read QR',
                    message: 'Please try with a clearer image.',
                    indicator: 'orange'
                });
            });
    };

    input.click();
}

