/* Time window definitions */
var MEAL_WINDOWS = {
    Breakfast: { start: '09:00', end: '11:00', label: '9:00 AM – 11:00 AM' },
    Lunch:     { start: '12:30', end: '15:00', label: '12:30 PM – 3:00 PM'  },
    Dinner:    { start: '19:00', end: '22:00', label: '7:00 PM – 10:00 PM'  }
};

function _pad2(n) { return String(n).padStart(2, '0'); }

function _getCurrentHHMM() {
    var now = new Date();
    return _pad2(now.getHours()) + ':' + _pad2(now.getMinutes());
}

function _checkMealWindow(mealType) {
    var hhmm = _getCurrentHHMM();
    var win  = MEAL_WINDOWS[mealType];

    if (hhmm >= win.start && hhmm < win.end) {
        return { ok: true };
    }

    var activeNow = null;
    Object.keys(MEAL_WINDOWS).forEach(function(mt) {
        var w = MEAL_WINDOWS[mt];
        if (hhmm >= w.start && hhmm < w.end) activeNow = mt;
    });

    if (hhmm < MEAL_WINDOWS.Breakfast.start) {
        return {
            ok: false,
            title: 'Too Early',
            msg: 'You scanned the ' + mealType + ' QR.\n' +
                 'Its serving window is ' + win.label + '.\n\n' +
                 'First window (Breakfast) opens at 9:00 AM.'
        };
    }

    if (hhmm >= MEAL_WINDOWS.Dinner.end) {
        return {
            ok: false,
            title: 'Serving Closed',
            msg: 'All meal windows are closed for today.\n\n' +
                 'You scanned the ' + mealType + ' QR.\n' +
                 'Its window was ' + win.label + '.'
        };
    }

    if (activeNow) {
        return {
            ok: false,
            title: 'Wrong QR',
            msg: 'You scanned the ' + mealType + ' QR,\n' +
                 'but the current serving window is ' + activeNow +
                 ' (' + MEAL_WINDOWS[activeNow].label + ').\n\n' +
                 mealType + ' window: ' + win.label + '.\n' +
                 'Please scan the ' + activeNow + ' QR instead.'
        };
    }

    var nextMeal = null;
    var order = ['Breakfast', 'Lunch', 'Dinner'];
    for (var i = 0; i < order.length; i++) {
        if (hhmm < MEAL_WINDOWS[order[i]].start) { nextMeal = order[i]; break; }
    }

    return {
        ok: false,
        title: 'Window Closed',
        msg: mealType + ' serving window is closed.\n' +
             'Window was ' + win.label + '.\n\n' +
             (nextMeal
                 ? 'Next: ' + nextMeal + ' opens at ' + MEAL_WINDOWS[nextMeal].label.split('–')[0].trim() + '.'
                 : 'No more windows today.')
    };
}

function logQRScan(data) {

    if (!data || data.indexOf('FQR|') !== 0) {
        frappe.msgprint({ title: 'Invalid QR', message: 'This is not a valid Food QR.', indicator: 'red' });
        $('#scan-result').html('');
        return;
    }

    var parts = data.split('|');
    if (parts.length < 4) {
        frappe.msgprint({ title: 'Invalid QR', message: 'QR data corrupted.', indicator: 'red' });
        $('#scan-result').html('');
        return;
    }

    var qrDate = parts[1];
    var meal   = parts[2];
    var user   = APP.employeeId;

    var today = frappe.datetime.nowdate();
    if (qrDate !== today) {
        frappe.msgprint({
            title: 'Wrong Date',
            message: 'This QR is for ' + qrDate + ', not today (' + today + ').\nPlease scan today\'s QR.',
            indicator: 'red'
        });
        $('#scan-result').html('');
        return;
    }

    if (!MEAL_WINDOWS[meal]) {
        frappe.msgprint({ title: 'Invalid QR', message: 'Unknown meal type: ' + meal, indicator: 'red' });
        $('#scan-result').html('');
        return;
    }

    var timeCheck = _checkMealWindow(meal);
    if (!timeCheck.ok) {
        frappe.msgprint({ title: timeCheck.title, message: timeCheck.msg, indicator: 'orange' });
        $('#scan-result').html('');
        return;
    }

    if (!user) {
        frappe.msgprint({ title: 'Error', message: 'User not identified.', indicator: 'red' });
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Food Count',
            filters: [
                ['user',       '=', user],
                ['order_date', '=', qrDate]
            ],
            fields: ['name', 'breakfast_selected', 'lunch_selected', 'dinner_selected',
                     'breakfast_status', 'lunch_status', 'dinner_status'],
            limit: 1
        },
        callback: function(r) {

            if (!r.message || r.message.length === 0) {
                frappe.msgprint({
                    title: 'Not Ordered',
                    message: 'You did not order food for today.\nOrders must be placed the previous day.',
                    indicator: 'orange'
                });
                $('#scan-result').html('');
                return;
            }

            var order      = r.message[0];
            var itemField  = meal.toLowerCase();
            var statusField = itemField + '_status';

            var selectedField = itemField + '_selected';

            if (!order[selectedField]) {
                frappe.msgprint({
                    title: 'Meal Not Ordered',
                    message: 'You did not order ' + meal + ' for today.\nOnly ordered meals can be collected.',
                    indicator: 'orange'
                });
                $('#scan-result').html('');
                return;
            }

            if (order[statusField] === 'Consumed') {
                frappe.msgprint({
                    title: 'Already Used',
                    message: meal + ' already consumed. Duplicate scans are not allowed.',
                    indicator: 'orange'
                });
                $('#scan-result').html('');
                return;
            }

            frappe.call({
                method: 'finstein_hrms.api.scan_food_qr',
                args: { qr_data: data },
                callback: function(scanRes) {
                    if (scanRes.message && scanRes.message.success) {
                        frappe.show_alert({ message: '✅ ' + meal + ' marked as Consumed!', indicator: 'green' }, 5);
                        loadTodayStatus();
                    }
                },
                error: function() {
                    $('#scan-result').html('');
                }
            });
        }
    });
}

