/* ============================================================
   FEEDBACK — bottom sheet
============================================================ */
function openFeedback() {
    if (!APP.employeeId) {
        frappe.msgprint({ title: 'Error', message: 'User not found.', indicator: 'red' });
        return;
    }

    // Reset remarks
    $('#fb-bfast-remarks, #fb-lunch-remarks, #fb-dinner-remarks').val('');

    // Default all to Yes
    $('.fb-toggle-group').each(function() {
        $(this).find('.fb-toggle').removeClass('active');
        $(this).find('.fb-toggle[data-val="1"]').addClass('active');
    });

    // Auto-fill Yes/No from today's Food Count consumed status
    var today = frappe.datetime.nowdate();
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Food Count',
            filters: [
                ['user',       '=', APP.employeeId],
                ['order_date', '=', today]
            ],
            fields: ['breakfast_selected','lunch_selected','dinner_selected',
                     'breakfast_status','lunch_status','dinner_status'],
            limit: 1
        },
        callback: function(r) {
            var order = r.message && r.message.length > 0 ? r.message[0] : null;

            // Helper: set toggle based on consumed status
            function setToggle(groupId, item, status) {
                var isYes = (item && status === 'Consumed') ? '1' : '0';
                $('#' + groupId + ' .fb-toggle').removeClass('active');
                $('#' + groupId + ' .fb-toggle[data-val="' + isYes + '"]').addClass('active');
            }

            if (order) {
                setToggle('fb-bfast-toggle',  order.breakfast_selected, order.breakfast_status);
                setToggle('fb-lunch-toggle',  order.lunch_selected,     order.lunch_status);
                setToggle('fb-dinner-toggle', order.dinner_selected,    order.dinner_status);
            }

            $('#feedback-overlay').addClass('open');
        },
        error: function() {
            // Open anyway with defaults
            $('#feedback-overlay').addClass('open');
        }
    });
}

function submitFeedback() {
    var bfastConsumed = parseInt($('#fb-bfast-toggle .fb-toggle.active').data('val'));
    var lunchConsumed = parseInt($('#fb-lunch-toggle .fb-toggle.active').data('val'));
    var dinnerConsumed= parseInt($('#fb-dinner-toggle .fb-toggle.active').data('val'));
    var bfastRemarks  = $('#fb-bfast-remarks').val().trim();
    var lunchRemarks  = $('#fb-lunch-remarks').val().trim();
    var dinnerRemarks = $('#fb-dinner-remarks').val().trim();

    $('#fb-submit-btn').prop('disabled', true).text('Submitting...');

    frappe.call({
        method: 'frappe.client.insert',
        args: {
            doc: {
                doctype:            'Food Report',
                user:               APP.employeeId,
                report_date:        frappe.datetime.nowdate(),
                breakfast_consumed: bfastConsumed,
                breakfast_remarks:  bfastRemarks,
                lunch_consumed:     lunchConsumed,
                lunch_remarks:      lunchRemarks,
                dinner_consumed:    dinnerConsumed,
                dinner_remarks:     dinnerRemarks
            }
        },
        freeze: true,
        freeze_message: 'Saving feedback...',
        callback: function(r) {
            $('#fb-submit-btn').prop('disabled', false).text('✅ Submit Feedback');
            if (r.message) {
                frappe.show_alert({ message: '🙏 Feedback saved!', indicator: 'green' }, 5);
                $('#feedback-overlay').removeClass('open');
            }
        },
        error: function() {
            $('#fb-submit-btn').prop('disabled', false).text('✅ Submit Feedback');
            frappe.msgprint({ title: 'Error', message: 'Could not save feedback. Please try again.', indicator: 'red' });
        }
    });
}

/* ============================================================
   TODAY STATUS
============================================================ */
function loadTodayStatus() {
    var today = frappe.datetime.nowdate();

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Food Count',
            filters: [
                ['user',       '=', APP.employeeId],
                ['order_date', '=', today]
            ],
            fields: ['name','breakfast_selected','lunch_selected','dinner_selected',
                     'breakfast_status','lunch_status','dinner_status'],
            limit: 1
        },
        callback: function(r) {
            var meals = [
                { key: 'breakfast', icon: '🌅', label: 'Breakfast' },
                { key: 'lunch',     icon: '☀️',  label: 'Lunch'     },
                { key: 'dinner',    icon: '🌙',  label: 'Dinner'    }
            ];

            var order = r.message && r.message.length > 0 ? r.message[0] : null;

            var pillsHtml = '';
            var consumed = 0, pending = 0, missed = 0, notOrdered = 0;

            meals.forEach(function(m) {
                var status = 'Not Ordered';
                var cls    = 'nordered';
                var statusLabel = '—';

                if (order && order[m.key + '_selected']) {
                    status = order[m.key + '_status'] || 'Pending';
                    if (status === 'Consumed')    { cls = 'consumed'; statusLabel = 'Consumed'; consumed++; }
                    else if (status === 'Pending'){ cls = 'pending';  statusLabel = 'Pending';  pending++;  }
                    else                          { cls = 'missed';   statusLabel = 'Missed';   missed++;   }
                } else {
                    notOrdered++;
                }

                pillsHtml +=
                    '<div class="tsc-pill ' + cls + '">' +
                    '<span class="pill-icon">' + m.icon + '</span>' +
                    '<span class="pill-label">' + m.label + '</span>' +
                    '<span class="pill-status">' + statusLabel + '</span>' +
                    '</div>';
            });

            $('#tsc-pills').html(pillsHtml);

            var countsHtml =
                '<div class="tsc-count-item"><span class="tsc-count-num" style="color:#27ae60">' + consumed + '</span><span class="tsc-count-lbl">Consumed</span></div>' +
                '<div class="tsc-count-item"><span class="tsc-count-num" style="color:#e67e00">' + pending  + '</span><span class="tsc-count-lbl">Pending</span></div>'  +
                '<div class="tsc-count-item"><span class="tsc-count-num" style="color:#e74c3c">' + missed   + '</span><span class="tsc-count-lbl">Missed</span></div>'   +
                '<div class="tsc-count-item"><span class="tsc-count-num">' + notOrdered + '</span><span class="tsc-count-lbl">Not Ordered</span></div>';

            $('#tsc-counts').html(countsHtml);
        }
    });
}

