/* ============================================================
   REPORT — generate table
============================================================ */
function generateReport() {
    var from = $('#report-from').val();
    var to   = $('#report-to').val();

    if (!from || !to) {
        frappe.msgprint({ title: 'Select Dates', message: 'Please select both From and To dates.', indicator: 'orange' });
        return;
    }
    if (from > to) {
        frappe.msgprint({ title: 'Invalid Range', message: 'From date must be before To date.', indicator: 'orange' });
        return;
    }

    $('#report-output').html('<p style="text-align:center;color:#aaa;padding:20px;font-size:13px;">⏳ Loading...</p>');

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Food Count',
            filters: [
                ['user',       '=', APP.employeeId],
                ['order_date', '>=', from],
                ['order_date', '<=', to]
            ],
            fields: ['order_date','breakfast_selected','lunch_selected','dinner_selected',
                     'breakfast_status','lunch_status','dinner_status'],
            order_by: 'order_date asc',
            limit: 200
        },
        callback: function(r) {
            var rows = r.message || [];

            if (rows.length === 0) {
                $('#report-output').html(
                    '<div class="report-empty">No records found for the selected range.</div>'
                );
                return;
            }

            // Fine logic: 75 per unconsumed ordered meal per day
            function calcFine(row) {
                var fine = 0;
                ['breakfast','lunch','dinner'].forEach(function(m) {
                    if (row[m + '_selected']) { // was ordered
                        var st = row[m + '_status'];
                        if (st !== 'Consumed') fine += 75;
                    }
                });
                return fine;
            }

            function statusBadge(item, status) {
                if (!item) return '<span class="badge-none">—</span>';
                if (status === 'Consumed') return '<span class="badge-consumed">✔ Consumed</span>';
                if (status === 'Pending')  return '<span class="badge-pending">⏳ Pending</span>';
                return '<span class="badge-missed">✘ Missed</span>';
            }

            function fmtDate(d) {
                var parts = d.split('-');
                return parts[2] + '/' + parts[1] + '/' + parts[0];
            }

            var totalFine = 0, totalConsumed = 0, totalMissed = 0;

            var tblRows = '';
            rows.forEach(function(row) {
                var fine = calcFine(row);
                totalFine += fine;

                ['breakfast','lunch','dinner'].forEach(function(m) {
                    if (row[m + '_selected'] && row[m + '_status'] === 'Consumed') totalConsumed++;
                    if (row[m + '_selected'] && row[m + '_status'] !== 'Consumed') totalMissed++;
                });

                tblRows +=
                    '<tr>' +
                    '<td>' + fmtDate(row.order_date) + '</td>' +
                    '<td>' + statusBadge(row.breakfast_selected, row.breakfast_status) + '</td>' +
                    '<td>' + statusBadge(row.lunch_selected,     row.lunch_status)     + '</td>' +
                    '<td>' + statusBadge(row.dinner_selected,    row.dinner_status)    + '</td>' +
                    '<td>' + (fine > 0
                        ? '<span class="fine-cell">₹' + fine + '</span>'
                        : '<span class="fine-zero">₹0</span>') +
                    '</td>' +
                    '</tr>';
            });

            // Store rows for download
            APP._reportRows = rows;
            APP._reportFrom = from;
            APP._reportTo   = to;

            var html =
                '<div class="report-table-wrap">' +
                '<table class="report-table">' +
                '<thead><tr>' +
                '<th>Date</th><th>Breakfast</th><th>Lunch</th><th>Dinner</th><th>Fine (₹)</th>' +
                '</tr></thead>' +
                '<tbody>' + tblRows + '</tbody>' +
                '</table></div>' +

                '<div class="report-summary">' +
                '<div class="report-sum-box"><span class="report-sum-num">' + rows.length + '</span><span class="report-sum-lbl">Days</span></div>' +
                '<div class="report-sum-box"><span class="report-sum-num" style="color:#27ae60">' + totalConsumed + '</span><span class="report-sum-lbl">Consumed</span></div>' +
                '<div class="report-sum-box"><span class="report-sum-num" style="color:#e74c3c">' + totalMissed + '</span><span class="report-sum-lbl">Missed</span></div>' +
                '<div class="report-sum-box fine-box"><span class="report-sum-num">₹' + totalFine + '</span><span class="report-sum-lbl">Total Fine</span></div>' +
                '</div>' +

                '<button class="report-dl-btn" onclick="downloadReportCSV()">⬇ Download CSV</button>';

            $('#report-output').html(html);
        }
    });
}

/* ============================================================
   REPORT — download CSV
============================================================ */
function downloadReportCSV() {
    var rows = APP._reportRows;
    if (!rows || !rows.length) return;

    function calcFine(row) {
        var fine = 0;
        ['breakfast','lunch','dinner'].forEach(function(m) {
            if (row[m + '_selected'] && row[m + '_status'] !== 'Consumed') fine += 75;
        });
        return fine;
    }

    function statusTxt(item, status) {
        if (!item) return 'Not Ordered';
        return status || 'Pending';
    }

    var csv = 'Date,Breakfast,Lunch,Dinner,Fine (INR)\n';
    rows.forEach(function(row) {
        var fine = calcFine(row);
        csv += [
            row.order_date,
            statusTxt(row.breakfast_selected, row.breakfast_status),
            statusTxt(row.lunch_selected,     row.lunch_status),
            statusTxt(row.dinner_selected,    row.dinner_status),
            fine
        ].join(',') + '\n';
    });

    var blob = new Blob([csv], { type: 'text/csv' });
    var url  = URL.createObjectURL(blob);
    var a    = document.createElement('a');
    a.href   = url;
    a.download = 'food_report_' + APP._reportFrom + '_to_' + APP._reportTo + '.csv';
    a.click();
    URL.revokeObjectURL(url);
}
